#!/usr/bin/env bash
# Runtime 模块
# 使用 pacman 安装系统级 Node.js / npm / Python / Go，并配置 mise 作为后续多版本管理器。

setup_mise_shell() {
  log_info "配置 mise shell 初始化"
  # shellcheck disable=SC2016
  append_unique_line 'eval "$(mise activate bash)"' "${HOME}/.bashrc"
  # shellcheck disable=SC2016
  append_unique_line 'eval "$(mise activate zsh)"' "${HOME}/.zshrc"
  write_mise_china_env_file
  log_warn "mise 初始化已写入 ~/.bashrc 和 ~/.zshrc，重新打开终端后完全生效"
}

shell_export_line() {
  local name="$1" value="$2"
  [[ -n "${value}" ]] || return 0
  printf 'export %s=%q\n' "${name}" "${value}"
}

mise_pyenv_repo_url() {
  local repo="${PYENV_REPO_URL:-https://github.com/pyenv/pyenv.git}"
  github_proxy_url "${repo}"
}

mise_go_repo_url() {
  local repo="${GO_REPO_URL:-https://github.com/golang/go}"
  printf '%s' "${repo}"
}

build_mise_china_env_args() {
  MISE_ENV_ARGS=()
  MISE_ENV_UNSET_ARGS=()
  local proxy

  [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]] || return 0

  [[ -n "${NODE_MIRROR_URL:-}" ]] && MISE_ENV_ARGS+=("MISE_NODE_MIRROR_URL=${NODE_MIRROR_URL}")
  [[ -n "${GO_DOWNLOAD_MIRROR:-}" ]] && MISE_ENV_ARGS+=("MISE_GO_DOWNLOAD_MIRROR=${GO_DOWNLOAD_MIRROR}")
  [[ -n "${GO_REPO_URL:-}" ]] && MISE_ENV_ARGS+=("MISE_GO_REPO=$(mise_go_repo_url)")
  [[ -n "${PYENV_REPO_URL:-}" ]] && MISE_ENV_ARGS+=("MISE_PYENV_REPO=$(mise_pyenv_repo_url)")
  [[ -n "${PYTHON_BUILD_MIRROR_URL:-}" ]] && MISE_ENV_ARGS+=("PYTHON_BUILD_MIRROR_URL=${PYTHON_BUILD_MIRROR_URL}")

  if [[ "${ENABLE_GITHUB_PROXY:-0}" -eq 1 && -n "${GITHUB_PROXY:-}" ]]; then
    proxy="$(normalize_url_slash "${GITHUB_PROXY}")"
    MISE_ENV_UNSET_ARGS+=("-u" "MISE_URL_REPLACEMENTS")
    MISE_ENV_ARGS+=(
      "GIT_CONFIG_COUNT=1"
      "GIT_CONFIG_KEY_0=url.${proxy}https://github.com/.insteadOf"
      "GIT_CONFIG_VALUE_0=https://github.com/"
    )
  fi
}

mise_run() {
  build_mise_china_env_args

  if [[ "${#MISE_ENV_ARGS[@]}" -gt 0 || "${#MISE_ENV_UNSET_ARGS[@]}" -gt 0 ]]; then
    run_cmd env "${MISE_ENV_UNSET_ARGS[@]}" "${MISE_ENV_ARGS[@]}" mise "$@"
  else
    run_cmd mise "$@"
  fi
}

write_mise_china_env_file() {
  [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]] || return 0

  local env_file="${HOME}/.config/archdevkit/mise-china.env"
  mkdir -p "$(dirname "${env_file}")"

  {
    echo "# Generated by ArchDevKit. Edit install_vars and rerun runtime to regenerate."
    echo "# Keep broad URL rewrites out of the default runtime path; language-specific mirrors are safer."
    echo "unset MISE_URL_REPLACEMENTS"
    shell_export_line "MISE_NODE_MIRROR_URL" "${NODE_MIRROR_URL:-}"
    shell_export_line "MISE_GO_DOWNLOAD_MIRROR" "${GO_DOWNLOAD_MIRROR:-}"
    shell_export_line "MISE_GO_REPO" "$(mise_go_repo_url)"
    shell_export_line "MISE_PYENV_REPO" "$(mise_pyenv_repo_url)"
    shell_export_line "PYTHON_BUILD_MIRROR_URL" "${PYTHON_BUILD_MIRROR_URL:-}"
  } > "${env_file}"

  append_unique_line "[[ -f \"${env_file}\" ]] && source \"${env_file}\"" "${HOME}/.bashrc"
  append_unique_line "[[ -f \"${env_file}\" ]] && source \"${env_file}\"" "${HOME}/.zshrc"
  log_info "mise 国内镜像环境变量已写入 ${env_file}"
}

mise_setting_supported() {
  local key="$1" output
  need_cmd mise || return 1

  output="$(mise settings get "${key}" 2>&1)" && return 0
  [[ "${output}" != *"Unknown setting"* ]]
}

set_mise_setting_if_supported() {
  local key="$1" value="$2" fallback="$3"
  [[ -n "${value}" ]] || return 0

  if ! mise_setting_supported "${key}"; then
    log_warn "当前 mise 不支持 setting ${key}，改用 ${fallback} 环境变量兜底"
    return 0
  fi

  mise_run settings set "${key}" "${value}" || log_warn "mise setting ${key} 写入失败，安装过程会继续使用 ${fallback} 环境变量"
}

configure_mise_china_mirrors() {
  [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]] || return 0

  log_info "配置 mise 国内下载镜像"

  if [[ -n "${NODE_MIRROR_URL:-}" ]]; then
    log_info "配置 mise Node.js 镜像：${NODE_MIRROR_URL}"
    set_mise_setting_if_supported "node.mirror_url" "${NODE_MIRROR_URL}" "MISE_NODE_MIRROR_URL"
  fi

  if [[ -n "${GO_DOWNLOAD_MIRROR:-}" ]]; then
    log_info "配置 mise Go 下载镜像：${GO_DOWNLOAD_MIRROR}"
    set_mise_setting_if_supported "go.download_mirror" "${GO_DOWNLOAD_MIRROR}" "MISE_GO_DOWNLOAD_MIRROR"
  fi

  if [[ -n "${GO_REPO_URL:-}" ]]; then
    log_info "配置 mise Go 仓库：$(mise_go_repo_url)"
    set_mise_setting_if_supported "go.repo" "$(mise_go_repo_url)" "MISE_GO_REPO"
  fi

  if [[ -n "${PYENV_REPO_URL:-}" ]]; then
    log_info "配置 mise Python pyenv 仓库：$(mise_pyenv_repo_url)"
    set_mise_setting_if_supported "python.pyenv_repo" "$(mise_pyenv_repo_url)" "MISE_PYENV_REPO"
  fi

  if [[ -n "${PYTHON_BUILD_MIRROR_URL:-}" ]]; then
    log_info "配置 python-build 下载镜像：${PYTHON_BUILD_MIRROR_URL}"
  fi

  if [[ "${ENABLE_MISE_GITHUB_URL_REPLACEMENT:-0}" -eq 1 && "${ENABLE_GITHUB_PROXY:-0}" -eq 1 && -n "${GITHUB_PROXY:-}" ]]; then
    log_info "安装 runtime 时临时启用 git insteadOf：${GITHUB_PROXY}"
    log_warn "已禁用 broad MISE_URL_REPLACEMENTS，避免 Go/Python URL 被二次代理后 404"
  fi
}

install_runtime_env() {
  if is_done "runtime"; then
    log_info "Runtime 环境已处理，跳过"
    return 0
  fi

  local runtime_packages=(mise nodejs npm python python-pip go)
  if [[ "${ENABLE_COREPACK:-0}" -eq 1 ]]; then
    runtime_packages+=(corepack)
  fi

  log_info "开始安装 Runtime 环境：系统 Node.js/npm/Python/Go + mise 版本管理器"
  pacman_install "${runtime_packages[@]}"
  setup_mise_shell
  configure_mise_china_mirrors

  if [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]]; then
    log_info "配置 npm 国内源：${NPM_REGISTRY}"
    run_cmd npm config set registry "${NPM_REGISTRY}"

    log_info "配置 pip 国内源：${PIP_INDEX_URL}"
    run_cmd python -m pip config set global.index-url "${PIP_INDEX_URL}"
    run_cmd python -m pip config set install.trusted-host "${PIP_TRUSTED_HOST}" || true
  fi

  verify_runtime
  mark_done "runtime"
  log_info "Runtime 环境安装完成"
}

verify_runtime() {
  log_info "验证 Runtime 版本"
  run_cmd mise --version
  run_cmd node -v
  run_cmd npm -v
  run_cmd python --version
  run_cmd python -m pip --version
  run_cmd go version
  if [[ "${ENABLE_COREPACK:-0}" -eq 1 ]]; then
    run_cmd corepack --version
  fi
}

ensure_runtime() {
  if ! is_done "runtime"; then
    install_runtime_env
  fi
}
